+
+fn verify_qe_report_policy(quote: &Quote, qe_identity: &QeIdentity) -> Result<()> {
+    let report = &quote.qe_report_body;
+    let id = &qe_identity.enclave_identity;
+
+    // miscselect check with mask
+    let misc_mask = u32::from_str_radix(id.miscselect_mask.trim_start_matches("0x"), 16)
+        .map_err(|_| VerifyError::InvalidCollateral("invalid qe_identity.miscselectMask".into()))?;
+    let misc_ref = u32::from_str_radix(id.miscselect.trim_start_matches("0x"), 16)
+        .map_err(|_| VerifyError::InvalidCollateral("invalid qe_identity.miscselect".into()))?;
+    if (report.misc_select & misc_mask) != (misc_ref & misc_mask) {
+        return Err(VerifyError::QeIdentityMismatch("QE miscselect policy mismatch".into()));
+    }
+
+    // attributes check with mask
+    let attr_mask = hex::decode(id.attributes_mask.trim_start_matches("0x"))
+        .map_err(|_| VerifyError::InvalidCollateral("invalid qe_identity.attributesMask".into()))?;
+    let attr_ref = hex::decode(id.attributes.trim_start_matches("0x"))
+        .map_err(|_| VerifyError::InvalidCollateral("invalid qe_identity.attributes".into()))?;
+    if attr_mask.len() != report.attributes.len() || attr_ref.len() != report.attributes.len() {
+        return Err(VerifyError::InvalidCollateral("unexpected qe_identity attribute length".into()));
+    }
+    for i in 0..report.attributes.len() {
+        if (report.attributes[i] & attr_mask[i]) != (attr_ref[i] & attr_mask[i]) {
+            return Err(VerifyError::QeIdentityMismatch("QE attributes policy mismatch".into()));
+        }
+    }
+
+    // signer / product id checks
+    let mr_signer_ref = hex::decode(id.mrsigner.trim_start_matches("0x"))
+        .map_err(|_| VerifyError::InvalidCollateral("invalid qe_identity.mrsigner".into()))?;
+    if mr_signer_ref.as_slice() != report.mr_signer.as_slice() {
+        return Err(VerifyError::QeIdentityMismatch("QE mrsigner mismatch".into()));
+    }
+    if id.isvprodid != report.isv_prod_id {
+        return Err(VerifyError::QeIdentityMismatch("QE isvprodid mismatch".into()));
+    }
+
+    // ISVSVN check against the first up-to-date tcb level
+    let min_isvsvn = id
+        .tcb_levels
+        .iter()
+        .find(|lvl| lvl.tcb_status == "UpToDate" || lvl.tcb_status == "SWHardeningNeeded")
+        .map(|lvl| lvl.tcb.isvsvn)
+        .ok_or_else(|| VerifyError::InvalidCollateral("no acceptable QE TCB level in qe_identity".into()))?;
+    if report.isv_svn < min_isvsvn {
+        return Err(VerifyError::QeIdentityMismatch("QE isvsvn below trusted level".into()));
+    }
+
+    Ok(())
+}
