+package org.apache.streampipes.rest.shared.security;
+
+import java.net.IDN;
+import java.net.Inet6Address;
+import java.net.InetAddress;
+import java.net.URI;
+import java.net.URISyntaxException;
+import java.net.UnknownHostException;
+import java.util.Locale;
+import java.util.Set;
+
+public final class SafeUrlValidator {
+
+  private static final Set<String> ALLOWED_SCHEMES = Set.of("https");
+
+  private SafeUrlValidator() {
+  }
+
+  public static boolean isSafeRemoteHttpUrl(String rawUrl) {
+    if (rawUrl == null || rawUrl.isBlank()) {
+      return false;
+    }
+
+    final URI uri;
+    try {
+      uri = new URI(rawUrl.trim());
+    } catch (URISyntaxException e) {
+      return false;
+    }
+
+    if (uri.getScheme() == null || uri.getHost() == null) {
+      return false;
+    }
+
+    String scheme = uri.getScheme().toLowerCase(Locale.ENGLISH);
+    if (!ALLOWED_SCHEMES.contains(scheme)) {
+      return false;
+    }
+
+    final String asciiHost;
+    try {
+      asciiHost = IDN.toASCII(uri.getHost());
+    } catch (IllegalArgumentException e) {
+      return false;
+    }
+
+    // Hostname-based shortcuts to local interfaces
+    if ("localhost".equalsIgnoreCase(asciiHost)) {
+      return false;
+    }
+
+    try {
+      InetAddress[] addresses = InetAddress.getAllByName(asciiHost);
+      for (InetAddress address : addresses) {
+        if (!isPublicAddress(address)) {
+          return false;
+        }
+      }
+    } catch (UnknownHostException e) {
+      return false;
+    }
+
+    return true;
+  }
+
+  private static boolean isPublicAddress(InetAddress address) {
+    if (address.isAnyLocalAddress()
+        || address.isLoopbackAddress()
+        || address.isLinkLocalAddress()
+        || address.isSiteLocalAddress()
+        || address.isMulticastAddress()) {
+      return false;
+    }
+
+    byte[] bytes = address.getAddress();
+    // Carrier-grade NAT 100.64.0.0/10
+    if (bytes.length == 4) {
+      int first = bytes[0] & 0xFF;
+      int second = bytes[1] & 0xFF;
+      if (first == 100 && (second >= 64 && second <= 127)) {
+        return false;
+      }
+      // 169.254.0.0/16 (defensive; also covered by isLinkLocalAddress)
+      if (first == 169 && second == 254) {
+        return false;
+      }
+      return true;
+    }
+
+    if (address instanceof Inet6Address) {
+      int first = bytes[0] & 0xFF;
+      int second = bytes[1] & 0xFF;
+
+      // Unique local addresses fc00::/7
+      if ((first & 0xFE) == 0xFC) {
+        return false;
+      }
+
+      // Link-local unicast fe80::/10
+      if (first == 0xFE && (second & 0xC0) == 0x80) {
+        return false;
+      }
+
+      // ::1
+      if (address.isLoopbackAddress()) {
+        return false;
+      }
+    }
+
+    return true;
+  }
+}

